import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

// Wires release signing into android/app/build.gradle using JIZHANG_* properties
// from ~/.gradle/gradle.properties (user-level, outside the repo). Idempotent.
// android/ is regenerated by `npx expo prebuild`, so re-run this after every prebuild.
const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const gradlePath = join(root, 'android', 'app', 'build.gradle');

if (!existsSync(gradlePath)) {
  console.error('[signing] android/app/build.gradle not found. Run: npx expo prebuild -p android');
  process.exit(1);
}

let src = readFileSync(gradlePath, 'utf8');

if (src.includes('JIZHANG_STORE_FILE')) {
  console.log('[signing] already patched, nothing to do.');
  process.exit(0);
}

const OLD_SIGNING = `    signingConfigs {
        debug {
            storeFile file('debug.keystore')
            storePassword 'android'
            keyAlias 'androiddebugkey'
            keyPassword 'android'
        }
    }`;

const NEW_SIGNING = `    signingConfigs {
        debug {
            storeFile file('debug.keystore')
            storePassword 'android'
            keyAlias 'androiddebugkey'
            keyPassword 'android'
        }
        // Release signing reads credentials from ~/.gradle/gradle.properties.
        // Those values live outside this repo; never hardcode passwords here.
        release {
            def jzStoreFile = findProperty('JIZHANG_STORE_FILE')
            def jzStorePw = findProperty('JIZHANG_STORE_PASSWORD')
            def jzAlias = findProperty('JIZHANG_KEY_ALIAS')
            def jzKeyPw = findProperty('JIZHANG_KEY_PASSWORD')
            if (jzStoreFile && jzStorePw && jzAlias && jzKeyPw) {
                storeFile file(jzStoreFile)
                storePassword jzStorePw
                keyAlias jzAlias
                keyPassword jzKeyPw
            } else {
                logger.warn('JIZHANG_* signing properties missing in ~/.gradle/gradle.properties - release APK would be DEBUG-signed.')
                storeFile file('debug.keystore')
                storePassword 'android'
                keyAlias 'androiddebugkey'
                keyPassword 'android'
            }
        }
    }`;

const OLD_RELEASE = `            // Caution! In production, you need to generate your own keystore file.
            // see https://reactnative.dev/docs/signed-apk-android.
            signingConfig signingConfigs.debug`;

const NEW_RELEASE = `            signingConfig signingConfigs.release`;

if (!src.includes(OLD_SIGNING)) {
  console.error('[signing] signingConfigs block did not match the expected Expo template shape.');
  process.exit(1);
}
if (!src.includes(OLD_RELEASE)) {
  console.error('[signing] release buildType block did not match the expected Expo template shape.');
  process.exit(1);
}

src = src.replace(OLD_SIGNING, NEW_SIGNING).replace(OLD_RELEASE, NEW_RELEASE);
writeFileSync(gradlePath, src, 'utf8');
console.log('[signing] patched android/app/build.gradle -> release uses signingConfigs.release');
